void deleteFirst(SLLNode* &head)
{
    if (head == nullptr) return;
    if (head->next == head)
    {
        delete head;
        head = nullptr;
    }
    else
    {
        last = head;
        while (last->next != head) last = last->next;
        last->next = head->next;
        delete head;
        head = last->next;
    }
}

void deleteLast(SLLNode* &head)
{
    if (head == nullptr) return;
    if (head->next == head)
    {
        delete head;
        head = nullptr;
    }
    else
    {
        SLLNode *plast = head;
        while (plast->next->next != head) plast = plast->next;
        SLLNode *q = plast->next;
        plast->next = head;
        delete q;
    }
}

struct DLLNode
{
    ElementType data;
