};

void insertBefore(DLLNode* &head, DLLNode *p, ElementType x)
{
    DLLNode *q,*p1;
    q = new DLLNode;
    q->data = x;
    //danh sách rỗng
    if (head == nullptr)
    {
        q->prev = nullptr;
        q->next = nullptr;
        head = q;
    }
    else
    {
        if (head == p) //thêm vào đầu
        {
            q->prev = nullptr;
            q->next = p;
            p->prev = q;
            head = q;
        }
        else
        {
            p1 = p->prev;
            q->prev = p1;
            p1->next = q;
            q->next = p;
            p->prev = q;
        }
    }
}

void delete(DLLNode* &head, DLLLNode *p)
{
    if (head == p) // xóa phần tử đầu
    {
        head = p->next;
        if (head != nullptr)
            head->prev = nullptr;
    }
    else
    {
        p->prev->next = p->next;
        if (p->next != nullptr)
            p->next->prev = p->prev;
    }
    delete p;
}

