struct Stack{
    ElementType arr[MAX];
    int top;
};

boolean empty(Stack s)
{
    return s.top == -1;
}

void push(Stack &s, ElementType x)
{
    if(s.top < MAX)
    {
        s.arr[++s.top] = x;
    }
}

ElementType pop(Stack &s)
{
    if(! empty(s))
    {
        ElementType x = s.arr[s.top];
        s.top--;
        return x;
    }
}

struct Node {
    ElementType data;
    Node *next;
};

struct Stack {
    Node *top;
};

bool empty(Stack s)
{
    return (s.top == nullptr);
}

void push(Stack &s, ElementType x)
{
    Node *newNode;
    newNode = new Node;
    newNode->data = x;
    newNode->next = s.top;
    s.top = newNode;
}

ElementType pop(Stack &s)
{
    if (!empty(s))
    {
        Node *q;
        ElementType x;
        q = s.top;
        x = q->data;
        s.top = q->next;
        delete q;
        return x;
    }
}

